from pathlib import Path
import json, math, html
R=Path(__file__).resolve().parent
d=json.loads((R/'calisma/veri.json').read_text()); t=d['totals']; ms=d['months']; cs=d['channels']; ps=d['products']
INK='#193b36'; GREEN='#287b6c'; RUST='#b85737'; GOLD='#cfaa62'; MUTED='#6b7971'; LINE='#dce1d9'; BG='#f6f4ec'
months=['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara']
def tr(x,n=0): return f'{x:,.{n}f}'.replace(',','@').replace('.',',').replace('@','.')
def pct(x,n=1):return '%'+tr(x*100,n)
def esc(x):return html.escape(str(x))
def svg(body,w=920,h=300,label='Grafik'):
 return f'<svg viewBox="0 0 {w} {h}" role="img" aria-label="{label}" xmlns="http://www.w3.org/2000/svg"><title>{label}</title>{body}</svg>'
def txt(x,y,text,size=12,color=MUTED,anchor='start',weight=400):return f'<text x="{x}" y="{y}" fill="{color}" font-size="{size}" text-anchor="{anchor}" font-weight="{weight}">{esc(text)}</text>'
def line(x1,y1,x2,y2,color=LINE,dash=''):return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{color}" stroke-dasharray="{dash}"/>'
def monthly_chart():
 w,h=952,220;l,r,top,b=48,910,22,177; ymax=700000
 X=lambda i:l+(r-l)*(i+.5)/12;Y=lambda v:b-v/ymax*(b-top)
 out=''
 for n in [0,200000,400000,600000]:out+=line(l,Y(n),r,Y(n))+txt(l-9,Y(n)+4,tr(n/1000),11,anchor='end')
 out+=txt(l,12,'bin TL',10)
 for i,m in enumerate(ms):
  x=X(i);out+=f'<rect x="{x-21}" y="{Y(m["net"])}" width="42" height="{b-Y(m["net"])}" rx="3" fill="{GREEN}"><title>{months[i]}: {tr(m["net"],2)} TL net satış</title></rect>'+txt(x,b+20,months[i],12,anchor='middle')
 bes=[(m['rent']+m['staff']+m['marketing'])/m['contribution_rate'] for m in ms]
 out+=f'<polyline points="{" ".join(f"{X(i)},{Y(v)}" for i,v in enumerate(bes))}" fill="none" stroke="{RUST}" stroke-width="2.5" stroke-dasharray="6 3"/>'
 out+=txt(X(9),Y(bes[9])-12,'462',12,RUST,'middle',700)
 return svg(out,w,h,'Aylık net satış ve yaklaşık başa baş satış; bin TL')
def return_chart():
 w,h=952,225;l,r,top,b=46,890,24,174;X=lambda i:l+(r-l)*i/11;Y=lambda x:b-x/.20*(b-top)
 out=f'<rect x="{X(7)-20}" y="{top}" width="{r-X(7)+40}" height="{b-top}" fill="#f7e9e1"/>'
 for v in [0,.05,.1,.15,.2]:out+=line(l,Y(v),r,Y(v))+txt(l-10,Y(v)+4,pct(v,0),11,anchor='end')
 for channel,col in [('Trendyol',RUST),('Diğer kanallar',GREEN)]:
  vals=[]
  for i in range(12):
   rows=[x for x in d['monthly_channels'] if x['month']==f'2025-{i+1:02}' and ((x['channel']=='Trendyol')==(channel=='Trendyol'))]
   vals.append(sum(x['returns'] for x in rows)/sum(x['orders'] for x in rows))
  out+=f'<polyline points="{" ".join(f"{X(i)},{Y(v)}" for i,v in enumerate(vals))}" fill="none" stroke="{col}" stroke-width="3"/>'
  for i,v in enumerate(vals):out+=f'<circle cx="{X(i)}" cy="{Y(v)}" r="3.5" fill="{col}"><title>{channel} {months[i]}: {pct(v,2)}</title></circle>'
  out+=txt(r+12,Y(vals[-1])+4,pct(vals[-1]),12,col,weight=700)
 for i in range(12):out+=txt(X(i),b+21,months[i],11,anchor='middle')
 out+=txt(X(7)+4,16,'Ağustostan itibaren %14–17 bandı',11,RUST)
 return svg(out,w,h,'Trendyol ve diğer kanallarda aylık sipariş bazlı iade oranı')
def waterfall():
 vals=[('Net satış',t['net']),('Hammadde',-t['material']),('Personel',-t['staff']),('Kira',-t['rent']),('Pazarlama',-t['marketing']),('Kargo',-t['shipping']),('Kalan',t['result'])]
 w,h=635,310;l,r,top,b=46,624,34,250;Y=lambda v:b-v/5300000*(b-top);out='';step=(r-l)/len(vals);cur=0
 for x in [0,2000000,4000000]:out+=line(l,Y(x),r,Y(x))+txt(l-9,Y(x)+4,tr(x/1e6),11,anchor='end')
 out+=txt(l,17,'milyon TL',11)
 for i,(label,v) in enumerate(vals):
  x=l+i*step+12;after=v if i in [0,6] else cur+v;start=0 if i in[0,6] else after;end=v if i in[0,6] else cur
  y=Y(end);hh=max(Y(start)-y,2);col=GREEN if i in[0,6] else '#b9c7bb'
  out+=f'<rect x="{x}" y="{y}" width="50" height="{hh}" rx="2" fill="{col}"/>'
  out+=txt(x+25,y-9,tr(abs(v)/1e6,2),12,INK,'middle',700)+txt(x+25,b+20,label,10,anchor='middle')
  if i<6:out+=line(x+50,Y(after),x+step,Y(after),MUTED,'2 3')
  cur=after
 return svg(out,w,h,'Net satıştan bilinen giderler sonrası sonuca geçiş, milyon TL')
def products_chart():
 w,h=525,258;l=195;r=440;out=''
 short={'Demlik Seti (el yapımı)':'Demlik Seti','İnce Belli Bardak 6lı':'İnce Belli Bardak 6lı','Karadeniz Sabahı 250g':'Karadeniz Sabahı','Adaçaylı Bergamot 100g':'Adaçaylı Bergamot','Kadıköy Akşamı 250g':'Kadıköy Akşamı','Demleme Atölyesi':'Demleme Atölyesi'}
 for i,p in enumerate(ps):
  y=26+i*38;ww=p['net']/1800000*(r-l);col=GREEN if i<2 else '#a2b5a7'
  out+=txt(l-12,y+10,short[p['product']],12,INK,'end')+f'<rect x="{l}" y="{y-4}" width="{ww}" height="22" rx="2" fill="{col}"/>'+txt(l+ww+9,y+11,tr(p['net']/1000),12,INK)
 out+=txt(l,h-2,'Net satış · bin TL',11)
 return svg(out,w,h,'Ürün bazında yıllık net satış, bin TL')
def product_trends():
 w,h=402,171;l,r,top,b=38,388,20,125;out='';X=lambda i:l+(r-l)*i/11;Y=lambda v:b-v/230000*(b-top)
 for v in [0,100000,200000]:out+=line(l,Y(v),r,Y(v))+txt(l-7,Y(v)+4,str(int(v/1000)),10,anchor='end')
 for name,col in [('İnce Belli Bardak 6lı',GREEN),('Adaçaylı Bergamot 100g',RUST),('Kadıköy Akşamı 250g',GOLD)]:
  vals={x['month']:x['net'] for x in d['monthly_products'] if x['product']==name}
  pts=[f'{X(i)},{Y(vals[f"2025-{i+1:02}"])}' for i in range(12) if f'2025-{i+1:02}' in vals]
  out+=f'<polyline points="{" ".join(pts)}" stroke="{col}" stroke-width="2.5" fill="none"/>'
 for i in [0,3,6,9,11]:out+=txt(X(i),b+20,months[i],10,anchor='middle')
 out+=txt(l,10,'bin TL',10)
 return svg(out,w,h,'Bardak ve çay ürünlerinde aylık net satış; Kadıköy Akşamı ilk kez Ekimde gözleniyor')
def logo():return '<svg viewBox="0 0 36 36" aria-hidden="true"><path d="M5 14h23v9a8 8 0 0 1-8 8h-7a8 8 0 0 1-8-8zM28 17h3a4 4 0 0 1 0 8h-3" fill="none" stroke="currentColor" stroke-width="2"/><path d="M11 10c-5-4 5-5 0-9M19 10c-5-4 5-5 0-9" fill="none" stroke="currentColor" stroke-width="1.7"/></svg>'
def top(k,title='2025 Yönetim Raporu'):return f'<div class="mast"><span class="brand">{logo()}DEMLİK</span><span>{title}</span><span class="chapter">{k}</span></div>'
def footer(n,source='Kaynak: demlik-satis-2025.xlsx · Temizlenmiş 2025 verisi'):return f'<footer><span>{source}</span><span>DEMLİK / 2025</span><b>{n:02}</b></footer>'
def page(n,k,body):return f'<section class="page" id="s{n}" aria-label="{k}">{top(k)}{body}{footer(n)}</section>'
def legend(items):return '<div class="legend">'+''.join(f'<span><i style="background:{c}"></i>{v}</span>' for v,c in items)+'</div>'
def metric(v,label,sub=''):return f'<div class="metric"><div class="metric-number">{v}</div><b>{label}</b><small>{sub}</small></div>'
def head(k,h,sub=''):return f'<div class="eyebrow">{k}</div><h2>{h}</h2>'+ (f'<p class="deck">{sub}</p>' if sub else '')

body1=f'''<div class="cover-grid"><div><div class="eyebrow">Yıllık değerlendirme / Ocak–Aralık 2025</div><h1>Satış güçlü.<br>Hareket alanı<br><em>çok dar.</em></h1><p class="lead">4,91 milyon TL net satıştan, dosyadaki giderler sonrası <strong>70,8 bin TL</strong> kalıyor. İlk öncelik satış hacmini büyütmek kadar, bu tutarı korumak.</p><div class="cover-rule"></div><p class="small">8.624 tekil sipariş · 6 ürün · 4 kanal<br>12 birebir kopya hariç; 365 gün kapsanıyor.</p></div><div class="hero-card"><span>HER 100 TL NET SATIŞTAN</span><div class="hero-value">1,44<small>TL</small></div><p>bilinen giderler sonrası kalıyor.</p><div class="hundred">{''.join('<i class="remaining"></i>' if i>=98 else '<i></i>' for i in range(100))}</div><small>100 birimlik alan; son iki hücre yaklaşık kalan payı gösterir.</small><div class="hero-note">Bu tutar muhasebe kârı değil.<br>Komisyon, vergi ve stok etkisi bilinmiyor.</div></div></div><div class="priorities"><div><span>01 / MALİ SONUÇ</span><h3>Giderleri tamamla</h3><p>Trendyol net satışına uygulanacak yalnız %5,72 ek maliyet, yıllık kalanı sıfırlar.</p></div><div><span>02 / OPERASYON</span><h3>İadeyi durdur</h3><p>Trendyol iade oranı ilk yarıda %2,72 iken ikinci yarıda %14,67.</p></div><div><span>03 / PLANLAMA</span><h3>Zayıf dönemi finanse et</h3><p>Mart–Ekim toplam sonucu −413,2 bin TL. Nakit takvimi ayrıca kurulmalı.</p></div></div>'''

body2=head('01 / SONUÇ VE BELİRSİZLİK','70,8 bin TL, eksik maliyetlere dayanıklı değil.','Kayıtlı giderlerle hesaplanan sonuç, net satışın yalnız %1,44’ü.')+f'''<div class="cols profit"><div><h3>Satıştan kalan tutara</h3>{waterfall()}<div class="number-strip"><div><b>5.262.920</b><small>Liste değeri · TL</small></div><span>−</span><div><b>120.127</b><small>İndirim · TL</small></div><span>−</span><div><b>234.021</b><small>İade · TL</small></div><span>=</span><div><b>4.908.772</b><small>Net satış · TL</small></div></div></div><aside class="stress"><div class="eyebrow">KOMİSYON TESTİ / TAHMİN DEĞİL</div><h3>Görünmeyen gider neyi değiştirir?</h3><label for="commission">Trendyol net satışına ek oran <output id="rate-label">%10</output></label><input id="commission" type="range" min="0" max="20" step="0.5" value="10" aria-label="Varsayımsal Trendyol komisyon oranı"><div class="stress-result" id="stress-result">−53.058 TL</div><p id="stress-caption">%10 varsayımında, 123.846 TL ek gider sonrası yıllık sonuç.</p><div class="threshold"><strong>%5,72</strong><span>yıllık sonucu sıfırlayan ek oran</span></div><small>Gerçek komisyon oranı dosyada yok. Matrah 1.238.455 TL Trendyol net satışı; diğer eksik giderler dahil değil.</small></aside></div><div class="callout"><b>Önce doğru maliyet tabanı.</b> Hammadde gideri her ay net satışın yaklaşık %32’si. Bu düzenlilik, giderin tahmini olabileceğini düşündürüyor; faturalar ve stok hareketleriyle doğrulanmadan ürün kârlılığı hesabında kullanılmamalı.</div><p class="footnote">Sonuç = net satış − 1.572.529 TL hammadde − 1.704.000 TL personel − 1.020.000 TL kira − 318.000 TL pazarlama − 223.456 TL kargo. KDV durumu, ödeme komisyonları, finansman ve stok değişimi bilinmiyor.</p>'''

rows=''.join(f'<tr><th>{months[i]}</th><td>{tr(m["net"]/1000,1)}</td><td class="{"negative" if m["result"]<0 else "positive"}">{tr(m["result"]/1000,1)}</td><td>{pct(m["return_rate"])}</td><td>{tr((m["rent"]+m["staff"]+m["marketing"])/m["contribution_rate"]/1000,1)}</td></tr>' for i,m in enumerate(ms))
body3=head('02 / AYLIK DAYANIKLILIK','Yılı dört ay taşıyor.','Ocak, Şubat, Kasım ve Aralık pozitif; Mart–Ekim kesintisiz negatif sonuç veriyor.')+f'''<div class="chart-head"><h3>Satış, giderleri karşılamaya yetiyor mu?</h3>{legend([('Net satış',GREEN),('Yaklaşık başa baş',RUST)])}</div>{monthly_chart()}<div class="cols monthly-bottom"><div><table class="compact"><thead><tr><th>Ay</th><th>Net satış¹</th><th>Sonuç¹</th><th>İade</th><th>Başa baş¹</th></tr></thead><tbody>{rows}</tbody></table></div><div class="monthly-notes"><div class="stat-pair"><strong>−413,2<small>bin TL</small></strong><p>Mart–Ekim birikimli sonuç.<br>Tahsilat ve ödeme vadeleri olmadığı için nakit ihtiyacı değildir.</p></div><div class="stat-pair"><strong>399,8<small>bin TL / ay</small></strong><p>Yıllık ortalama maliyet yapısıyla yaklaşık başa baş net satış.</p></div><p><b>Ekim uyarısı:</b> Satış eylüle göre %11,5 artıyor; pazarlama 30 binden 65 bin TL’ye çıkıyor. Sonuç −23,1 bin TL’ye geriliyor. Bu birlikte değişim kampanyanın nedensel etkisini kanıtlamaz.</p><p class="footnote">¹ bin TL. Başa baş = (kira + personel + pazarlama) / katkı oranı. Hammadde ve kargo satışla oransal varsayılır. Tek yıllık desen kalıcı mevsimsellik kanıtı değildir.</p></div></div>'''

channelrows=''.join(f'<tr><th>{c["channel"]}</th><td>{tr(c["net"]/1000,1)}</td><td>{pct(c["net"]/t["net"])}</td><td class="{"negative" if c["channel"]=="Trendyol" else ""}">{pct(c["return_rate"],2)}</td><td>{tr(c["discount_tl"]/1000,1)}</td><td>{tr(c["shipping"]/1000,1)}</td></tr>' for c in cs)
body4=head('03 / KANAL VE İADE','İade sorunu Trendyol’da yoğunlaşıyor.','Ağustostaki ayrışma yıl sonuna kadar sürüyor. İlk iş, kanal bazında iade nedenlerini çözmek.')+f'''<div class="chart-head"><h3>Sipariş bazlı iade oranı</h3>{legend([('Trendyol',RUST),('Diğer kanallar',GREEN)])}</div>{return_chart()}<div class="cols channel-bottom"><div><table><thead><tr><th>Kanal</th><th>Net satış¹</th><th>Pay</th><th>İade</th><th>İndirim¹</th><th>Kargo¹</th></tr></thead><tbody>{channelrows}</tbody></table><p class="footnote">¹ bin TL. İade oranı = iade siparişi / tüm siparişler. Kanal bazında ürün maliyeti, komisyon ve reklam dağılımı yok; bu tablo kâr sıralaması değildir.</p></div><aside class="mini-insight"><b>227 / 402</b><p>İadelerin %56,5’i Trendyol’dan; kanalın net satış payı %25,2.</p><b>118,7 bin TL</b><p>Toplam indirimlerin %98,8’i Trendyol’da. İndirim ile iadeler arasında nedensellik kurulamaz.</p></aside></div><div class="callout"><b>30 günlük müdahale:</b> Ağustos–Aralık iadelerini ürün, paketleme, teslimat ve müşteri gerekçesine göre kodlayın. Önce son 50 iade dosyasını inceleyin; en büyük iki neden için birer pilot düzeltme başlatın.</div>'''

body5=head('04 / ÜRÜN PORTFÖYÜ','Gelirin üçte ikisi iki ekipman ürününden.','Demlik Seti ve İnce Belli Bardak toplam net satışın %66,3’ünü oluşturuyor. Stok ve kalite sürekliliği kritik.')+f'''<div class="cols product-grid"><div><h3>Gelir yoğunlaşması</h3>{products_chart()}<div class="tea-note"><strong>%9,5</strong><p>Çay satışlarında kargo / net satış.<br>Ekipmanda aynı oran %2,6.</p></div></div><div><h3>Ürünlerdeki kırılma noktaları</h3>{legend([('Bardak',GREEN),('Bergamot',RUST),('Kadıköy',GOLD)])}{product_trends()}<div class="observation"><span>01</span><p><b>Bardakta nisan kırılması.</b> Mart 139,1 bin TL → nisan 20,2 bin TL: %85,5 düşüş. Stok kesintisi, erişim ve talep ayrı ayrı kontrol edilmeli; sebep dosyada yok.</p></div><div class="observation"><span>02</span><p><b>Bergamot geriliyor.</b> İlk çeyrek 178,1 bin TL → son çeyrek 57,8 bin TL: %67,5 düşüş. Ürün sayfası ve tekrar satın alma verisiyle teşhis edin.</p></div><div class="observation"><span>03</span><p><b>Kadıköy Akşamı ilk kez ekimde görünüyor.</b> Üç ayda 277,0 bin TL; son çeyrek satışının %16,4’ü. Diğer çayları ikame edip etmediği müşteri verisi olmadan bilinmez.</p></div></div></div><div class="callout"><b>Ticari test:</b> Çaylarda çoklu paket ve ekipmanla birlikte satış deneyin. Amaç sepet başına kargo yükünü düşürmek; başarıyı yalnız ciroyla değil, gerçek ürün maliyeti ve komisyon sonrası katkıyla ölçün.</div><p class="footnote">Fiyatlar yıl boyunca ürün bazında sabit. Dönemsel satış değişimleri bu dosyada fiyat artışıyla açıklanmıyor. Stok, dönüşüm, müşteri ve ürün maliyetleri bulunmadığından en kârlı ürün belirlenemez.</p>'''

body6=head('05 / UYGULAMA PLANI','Önümüzdeki 90 gün: ölç, düzelt, sonra büyüt.','Aşağıdaki sorumlular ve hedefler öneridir. Etkiler taahhüt ya da birleştirilebilir kâr tahmini değildir.')+'''<div class="action-grid"><article class="action"><div class="action-top"><span>İLK 7 GÜN</span><b>01</b></div><h3>Gerçek sonucu kapatın</h3><p class="owner">İşletme sahibi + muhasebe</p><p>Komisyon, ödeme masrafı, kargo faturası, KDV durumu ve stok hareketlerini satış defteriyle eşleştirin. 12 kopya ve altı kanal yazımını düzeltin.</p><div class="target"><span>Teslim ölçütü</span><b>12 ay için tam gider mutabakatı</b></div><small>Öncelik nedeni: ek gider eşiği yalnız 70,8 bin TL. Hammadde kayıtlarının yaklaşık %32 oranla oluşmasını ayrıca doğrulayın.</small></article><article class="action"><div class="action-top"><span>İLK 30 GÜN</span><b>02</b></div><h3>Trendyol iadelerini azaltın</h3><p class="owner">E-ticaret + operasyon</p><p>Son 50 iadeyi kodlayın. İlk iki neden için ürün açıklaması / paketleme pilotu yapın. Sonuçları iade süresi dolmuş sipariş gruplarında takip edin.</p><div class="target"><span>İlk pilot hedefi</span><b>İade oranını ≤ %5’e indirmek</b></div><small>%5 hedefi varsayımdır. 2025 ikinci yarı hacmi ve iade tutarı karması korunursa yaklaşık 70,5 bin TL satış geri kazanımı; gider ve komisyon öncesi.</small></article><article class="action"><div class="action-top"><span>30–90 GÜN</span><b>03</b></div><h3>Düşük dönemi planlayın</h3><p class="owner">İşletme sahibi + satış</p><p>13 haftalık tahsilat/ödeme planı kurun. Bardak stok sürekliliğini kontrol edin. Çay paketlerini küçük bütçeyle deneyin; reklam artışını katkı ölçümüne bağlayın.</p><div class="target"><span>Haftalık takip</span><b>Nakit planı + katkı + iade</b></div><small>Ek giderler hariç sabit gider tabanında %5 tasarruf, yıllık 152,1 bin TL etki yaratır. Hizmet ve satış kaybı riski test edilmeden uygulanmaz.</small></article></div><div class="weekly"><div><span>HER PAZARTESİ / 20 DAKİKA</span><h3>Bir sayfalık kontrol ritmi</h3></div><p><b>1.</b> Net satış ve aylık başa baş farkı<br><b>2.</b> Kanal bazlı olgunlaşmış iade oranı<br><b>3.</b> Stok kesintisi ve nakit planı sapması</p><p><b>4.</b> Komisyon dahil sipariş katkısı<br><b>5.</b> Reklam testi: ek katkı / ek harcama<br><b>6.</b> Aksiyon sahibi ve bir sonraki kontrol tarihi</p></div><p class="footnote">Satış geri kazanımı hesabı: [196 − (1.336 × %5)] × (106.897,25 / 196) = 70.465 TL. Sabit gider testi: (1.020.000 + 1.704.000 + 318.000) × %5 = 152.100 TL. İki etki toplanarak sonuç tahmini yapılmadı.</p>'''

body7=head('06 / YÖNTEM VE GÜVENİLİRLİK','Hangi sayı neyi anlatıyor?','Hesaplar aynı temizlenmiş kayıt setine dayanır. Kaynak dosya değiştirilmedi.')+f'''<div class="cols method-grid"><div><h3>Kaynak → analiz mutabakatı</h3><table><thead><tr><th>Kontrol</th><th>Sonuç</th></tr></thead><tbody><tr><th>Kaynak satış satırı</th><td>8.636</td></tr><tr><th>Birebir aynı fazla kayıt</th><td>12</td></tr><tr><th>Analize alınan tekil sipariş</th><td>8.624</td></tr><tr><th>İade / iade olmayan sipariş</th><td>402 / 8.222</td></tr><tr><th>Tutar formülü uyuşmazlığı</th><td>0</td></tr><tr><th>Boş kaynak hücresi</th><td>0</td></tr><tr><th>Gider kapsamı</th><td>12 ay / 4 kalem</td></tr></tbody></table><div class="reconcile"><b>Temizlemenin parasal etkisi</b><p>Net satış −5.398,25 TL<br>Kargo −318,00 TL<br>Bilinen giderler sonrası sonuç −5.080,25 TL</p><small>Ham sonuç 75.867,50 TL → temiz sonuç 70.787,25 TL. Kaynak giderler aynen korundu.</small></div><p class="footnote">Kaynak aralıkları: Satışlar A1:K8637; Giderler A1:E13.<br>Kopya siparişler: 10317, 10557, 10697, 12100, 12681, 13292, 15036, 16719, 16841, 17291, 17780, 18412.</p></div><div class="definitions"><h3>Hesap kuralları</h3><dl><dt>Net satış</dt><dd>Adet × birim fiyat − indirim − iade tutarı. “Tutar” alanı zaten indirim sonrası; indirim ikinci kez düşülmez.</dd><dt>İade</dt><dd>“Evet” tam iade kabul edilir. İade tarihi yok; satış tarihinin döneminden düşülür. Kayıtlı çıkış kargosu korunur.</dd><dt>Bilinen giderler sonrası sonuç</dt><dd>Net satıştan kargo, hammadde, kira, personel ve pazarlama çıkarılır. Net kâr, EBITDA veya nakit akışı değildir.</dd><dt>Ortalama iadesiz sipariş</dt><dd>4.908.772,25 TL / 8.222 = 597,03 TL. Siparişlerin her biri tek ürün satırıdır; müşteri başına harcama değildir.</dd><dt>Başa baş yaklaşımı</dt><dd>Katkı oranı %63,41; yıllık yaklaşık başa baş 4,797 milyon TL. Mevcut satış bunun yalnız %2,27 üzerindeki güvenlik payını taşır¹.</dd><dt>Güncellenebilir dosya</dt><dd>Excel, kaynak tablolar ve yıl seçimiyle hesaplanır. PDF/HTML bu raporun sabit 2025 görünümüdür; Excel değişince kendiliğinden değişmez.</dd></dl></div></div><div class="method-bottom"><b>Eksik veri:</b> Komisyon, vergi/KDV, tahsilat, stok, ürün maliyeti, müşteri kimliği, reklam ilişkilendirmesi ve iade nedeni. Bu nedenle kanal/ürün kârı, ROAS, müşteri tutma ve nakit ihtiyacı hesaplanmadı.</div><p class="footnote">¹ Güvenlik payı = (net satış − başa baş satış) / net satış. Üst başlıkta “üzerindeki” ifadesi bu payı anlatır; başa baş tutarına göre artış %2,33’tür. Tutarlar TL; grafiklerde belirtilen yerlerde bin / milyon TL. Yuvarlama farkları olabilir.</p>'''

